Here is a simple example of code in Swift that could be used to create a basic podcast app:

```
import UIKit

class PodcastViewController: UIViewController {

    var episodeData = [PodcastEpisode]()
    var selectedEpisode: PodcastEpisode?

    @IBOutlet weak var episodesLabel: UILabel!
    @IBOutlet weak var nowPlayingButton: UIButton!

    override func viewDidLoad() {
        super.viewDidLoad()

        // Load the podcast episodes from a data source
        let url = URL(string: "https://example.com/podcasts.json")!
        let task = URLSession.shared.dataTask(with: url) { (data, response, error) in
            guard let data = data else { return }
            do {
                let episodes = try JSONDecoder().decode([PodcastEpisode].self, from: data)
                DispatchQueue.main.async {
                    self.episodeData = episodes
                    self.episodesLabel.text = "Episodes: \(episodes.count)"
                }
            } catch {
                print("Error decoding podcast episodes: \(error)")
            }
        }
        task.resume()
    }

    @IBAction func togglePlayingButton(_ sender: Any) {
        if let selectedEpisode = selectedEpisode {
            // Pause the currently playing episode
            let currentPlayer = AudioManager.shared.players.first!
            currentPlayer.pause()
            selectedEpisode.isPlaying = false
            selectedEpisode.save()
        } else {
            // Play the first episode
            let firstEpisode = episodeData.first!
            AudioManager.shared.play(firstEpisode.url)
            selectedEpisode = firstEpisode
            episodesLabel.text = "Episode: \(firstEpisode.title)"
        }
    }

}

class PodcastEpisode: Identifiable, Codable {

    var id: String?
    var title: String
    var url: URL
    var isPlaying = false

    init(title: String, url: URL)
